-- VTID-05803 staging load probe (read-only, one row). Says which stage the staging database is ready for:
--   restore   public does not hold the restored schema yet (the 13 vector columns are missing)
--   pre-load  restored schema, vector columns are vector, nothing saved yet
--   dms       pre-load done: vector columns are text, foreign keys saved and dropped (the DMS load may run)
--   post-load vector columns text and foreign keys saved, with rows loaded (run the post-load)
--   done      post-load done: vector columns are vector again and every saved object is restored
SELECT 'PROBE' AS probe, (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r','p')) AS public_tables, (SELECT count(*) FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) x(t,c) JOIN pg_attribute a ON a.attrelid = to_regclass('public.' || x.t) AND a.attname = x.c AND NOT a.attisdropped JOIN pg_type ty ON ty.oid = a.atttypid WHERE ty.typname = 'vector') AS vector_cols, (SELECT count(*) FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) x(t,c) JOIN pg_attribute a ON a.attrelid = to_regclass('public.' || x.t) AND a.attname = x.c AND NOT a.attisdropped WHERE a.atttypid = 'text'::regtype) AS text_cols, (SELECT count(*) FROM pg_constraint k JOIN pg_namespace n ON n.oid = k.connamespace WHERE k.contype = 'f' AND n.nspname = 'public') AS public_fks, (SELECT count(*) FROM pg_constraint k JOIN pg_class r ON r.oid = k.confrelid JOIN pg_namespace n ON n.oid = r.relnamespace JOIN pg_namespace kn ON kn.oid = k.connamespace WHERE k.contype = 'f' AND n.nspname = 'auth' AND kn.nspname = 'public') AS public_to_auth_fks, to_regclass('migration_audit.saved_foreign_keys') IS NOT NULL AS audit, (SELECT count(*) FROM pg_namespace WHERE nspname = 'vtid05803_preexisting') AS preexisting_schema, coalesce((SELECT sum(c.reltuples)::bigint FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.reltuples > 0), 0) AS est_rows;
